breach.segment:
// Customise: alert when interactive queries were queued in >= 10 one-minute samples in the window.
// job/num_in_flight publishes up to ~12 minutes late, so a 30-minute window holds ~18 visible minutes.
// Minutes without a published sample are not counted as healthy or queued.
WHERE queued_minutes >= 10
| SORT queued_minutes DESC, peak_pending_jobs DESC
| LIMIT 50
